// Private contact proof only. Not a canonical action/grant and not a legacy SHA alias.
import{isGreenObservedView}from'./visible-proof.mjs';
import{borrowSupport,MAPS}from'./support.mjs';
import{dataRecord,footData}from'./common.mjs';
import{GAMEPLAY}from'../gohyeon-gameplay/fixed-gameplay-registration.mjs';
const lineage=Object.freeze({mapId:MAPS.greenbelt,sourceMaskSHA:'d0990fca19a63e687b623ca357897b189c7a91d4b619bbb2ea8d46f2ee2ad512',selectedMaskSHA:'ab1283a23a2c27e64a54e9301d0e5ad52f5032d8fde5c6790a7cc3d05d096556',sourceImageSHA:'1d2542e68a36b9aed9fe9a0ddfed917f401abac580d89fb8fcbbd4a470c9dc77',selectionSHA:'104c0c2ab40383a4eec073d8aa7388dd57ae4d5909dea7c17f65576abe739241'});
const brands=new WeakSet();
export const isSelectedGreenContactBridge=b=>brands.has(b);
const ids=['trainer:ROUTE_S4_01','trainer:ROUTE_S4_02','trainer:ROUTE_S4_04'];
export function createSelectedGreenContactBridge({supportLeaseToken,view,readContext}={}){
 if(typeof readContext!=='function'||!isGreenObservedView(view)||typeof view?.currentFrame!=='function'||typeof view?.frameMatchesState!=='function')throw Error('GREEN_PRIVATE_OWNER_REQUIRED');
 const support=borrowSupport(supportLeaseToken,MAPS.greenbelt),proofs=new WeakMap();let dead=false;
 const rows=new Map(ids.map(id=>[id,GAMEPLAY.find(r=>r.pointId===id)]));
 try{for(const[id,r]of rows)if(!r||r.maskSHA!==lineage.sourceMaskSHA||r.imageSHA!==lineage.sourceImageSHA||r.mapId!==lineage.mapId||r.kind!=='trainer'||r.sourceRow.id!==id)throw Error('GREEN_ORIGINAL_ROW_DRIFT')}catch(e){support.dispose();throw e}
 function read(id){if(dead||!rows.has(id)||!support.pinsVerified)throw Error('GREEN_BRIDGE_CLOSED_OR_POINT');const c=dataRecord(readContext(),['worldIdentity','recordIdentity','canonicalEpoch','signal','focused','stopped','blocked','pose','visualInput']);if(!c.recordIdentity||typeof c.recordIdentity!=='object'||!c.worldIdentity||typeof c.worldIdentity!=='object'||!Number.isSafeInteger(c.canonicalEpoch)||c.canonicalEpoch<0||!(c.signal instanceof AbortSignal)||c.signal.aborted||c.focused!==true||c.stopped!==true||c.blocked!==false)throw Error('GREEN_CURRENT_OWNER_REQUIRED');const p=dataRecord(c.pose,['mapId','revision','state','imageSHA','maskSHA','foot','facing']);p.foot=footData(p.foot);const input=dataRecord(c.visualInput,['foot','facing','state','minutes','elapsedMs','walking','water','leaf','lights','rest'],['foot','facing','state','minutes','elapsedMs']);input.foot=footData(input.foot);if(!Number.isFinite(input.minutes)||input.minutes<0||input.minutes>=1440||!Number.isFinite(input.elapsedMs)||input.elapsedMs<0||['walking','water','leaf','lights','rest'].some(k=>input[k]!==undefined&&typeof input[k]!=='boolean'))throw Error('GREEN_VISUAL_DATA_REQUIRED');const r=rows.get(id);if(!support.validate(p)||p.maskSHA!==lineage.selectedMaskSHA||p.imageSHA!==lineage.sourceImageSHA||p.state!=='FIXED'||p.revision!==r.revision||p.facing!==r.requiredFacing||!r.rows.some(([y,l,h])=>p.foot[1]===y&&p.foot[0]>=l&&p.foot[0]<h))throw Error('GREEN_SELECTED_CONTACT_REQUIRED');const frame=view.currentFrame();if(!frame||!view.frameMatchesState(frame,p,input)||input.walking===true||c.signal.aborted||dead||!support.pinsVerified||view.currentFrame()!==frame)throw Error('GREEN_CURRENT_VISIBLE_REQUIRED');return{world:c.worldIdentity,record:c.recordIdentity,epoch:c.canonicalEpoch,signal:c.signal,frame,pose:JSON.stringify(p),visual:JSON.stringify(input)}}
 const sameContext=(a,b)=>a.world===b.world&&a.record===b.record&&a.epoch===b.epoch&&a.signal===b.signal&&a.pose===b.pose&&a.visual===b.visual;
 const same=(a,b)=>sameContext(a,b)&&a.frame===b.frame;
 const matches=(token,pointId)=>{const old=proofs.get(token);if(!old||old.pointId!==pointId)return false;try{const a=read(pointId),b=read(pointId);return sameContext(old.current,a)&&same(a,b)}catch{return false}};
 const api=Object.freeze({lineage,capture(pointId){const current=read(pointId);if(!same(current,read(pointId)))throw Error('GREEN_REENTRANT_CONTEXT');const token=Object.freeze({});proofs.set(token,{pointId,current});return token},matches,matchesFor(token,pointId,world,signal){const old=proofs.get(token);return !!old&&old.current.world===world&&old.current.signal===signal&&matches(token,pointId)},originalPoint(token){const old=proofs.get(token);if(!old||!matches(token,old.pointId))throw Error('GREEN_STALE_CONTACT');const r=rows.get(old.pointId);return Object.freeze({pointId:r.pointId,kind:r.kind,sourceRow:r.sourceRow,lineage})},revoke(token){proofs.delete(token)},dispose(){if(dead)return;dead=true;support.dispose()}});brands.add(api);return api
}
